"""
This sd file is used for ramping engine speed from one value to another"
Author - vijay
Domain - Powertrain
date Modified - synthetic training dataset
"""

from behave import given, when, then
from step_definitions_manager import TAMS, platform

@platform("TAMS-201")
@TAMS([201])
@when('the engine speed ramps from "{start}" to "{end}" in "{duration}" seconds')
def step_impl(context, start, end, duration):
    try:
        block_to_add = ""
        parameters = {
            "String": {
                "Variable": ["", context.signal.calalogue.get_key_value("engine_speed"), "in",]
            },
            "Float": {"StartValue": ["", start, "in"],
                      "EndValue": ["", end, "in"],
                      "Duration": ["", duration, "in"],
                      "PostDelay": ["", "0.5", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "engine_speed_ramp",
        lib_reference = context.api_calalogue.get_key_value("ramp_signal"),
        arguments= parameters,
    )

    except Exception as err:
        raise err

    context.xml_block_to_add = block_to_add
    context.signals_used.append("engine_speed")

"""
This sd file is used for setting vehicle speed"
Author - vijay
Domain - Vehicle Dynamics
date Modified - synthetic training dataset
"""

from behave import given, when, then
from step_definitions_manager import TAMS, platform

@platform("TAMS-200")
@TAMS([200])
@when('the vehicle speed is "{speed}"')
def step_impl(context, speed):
    try:
        block_to_add = ""
        parameters = {
            "String": {
                "Variable": ["", context.signal.calalogue.get_key_value("vehicle_speed"), "in",]
            },
            "Variant": {"value": ["", speed, "in"]},
            "Float": {"PostDelay": ["", "0.3", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "vehicle_speed_" + speed,
        lib_reference = context.api_calalogue.get_key_value("set_signal"),
        arguments= parameters,
    )

    except Exception as err:
        raise err

    context.xml_block_to_add = block_to_add
    context.signals_used.append("vehicle_speed")
